            2'b11 : txd_dC = 1'b0;
            default : txd_dC = 1'b0;
          endcase
          if (baud_rate_edge_iC)
            begin
              state_dC = TXSTOP1;
            end

        end
      TXSTOP1 : 
        begin
          txd_dC = 1'b1;
          if (reg_read_iC.lcr.stop_bits)
            begin
              state_dC = TXIDLE;
            end
          else
            if (baud_rate_edge_iC)
              begin
                state_dC = TXSTOP2;
              end

        end
      TXSTOP2 : 
        begin
          txd_dC = 1'b1;
          if (word_len_bitsC==3'b100)
            begin
              if (double_rate_edge_iC)
                begin
                  state_dC = TXIDLE;
                end

            end
          else
            begin
              state_dC = TXIDLE;
            end
        end
      default : state_dC = TXIDLE;
    endcase
    if (reg_read_iC.fcr.fifo_en)
      begin
        fifo_clearC = 1'b0;
        if (reg_read_iC.fcr.tx_fifo_rst)
          begin
            fifo_clearC = 1'b1;
            reg_write_oC.fifo_rst = 1'b0;
            reg_write_oC.fifo_rst_valid = 1'b1;
          end

        if (fifo_emptyC)
          begin
            reg_write_oC.thr_empty = 1'b1;
            reg_write_oC.thr_valid = 1'b1;
            if (tsr_emptyC)
              begin
                reg_write_oC.tx_empty = 1'b1;
                reg_write_oC.empty_valid = 1'b1;
              end

          end

        if (thr_full_qVotedC&(~ fifo_fullC ))
          begin
            fifo_pushC = 1'b1;
            fifo_data_iC = reg_read_iC.thr.char_tx&word_len_maskC;
            thr_full_dC = 1'b0;
          end

      end

    if (~reg_read_iC.fcr.fifo_en)
      begin
        fifo_clearC = 1'b1;
        if (~thr_full_qVotedC)
          begin
            reg_write_oC.thr_empty = 1'b1;
            reg_write_oC.thr_valid = 1'b1;
            if (tsr_emptyC)
              begin
                reg_write_oC.tx_empty = 1'b1;
                reg_write_oC.empty_valid = 1'b1;
              end

          end

      end

  end

always_ff @( posedge clk_iA or negedge rst_niA )
  begin
    if (!rst_niA)
      begin
        thr_full_qA <= '0;
      end
    else
      begin
        thr_full_qA <= thr_full_dA;
      end
  end

always_ff @( posedge clk_iB or negedge rst_niB )
  begin
