      end
    else
      begin
        thr_full_qC <= thr_full_dC;
      end
  end

always_ff @( posedge clk_iA or negedge rst_niA )
  begin
    if (!rst_niA)
      begin
        tsr_qA <= '0;
        tsr_count_qA <= '0;
      end
    else
      begin
        tsr_qA <= tsr_dA;
        tsr_count_qA <= tsr_count_dA;
      end
  end

always_ff @( posedge clk_iB or negedge rst_niB )
