        tsr_count_qB <= '0;
      end
    else
      begin
        tsr_qB <= tsr_dB;
        tsr_count_qB <= tsr_count_dB;
      end
  end

always_ff @( posedge clk_iC or negedge rst_niC )
  begin
    if (!rst_niC)
      begin
        tsr_qC <= '0;
        tsr_count_qC <= '0;
      end
    else
      begin
        tsr_qC <= tsr_dC;
        tsr_count_qC <= tsr_count_dC;
      end
  end

always_ff @( posedge clk_iA or negedge rst_niA )
  begin
    if (!rst_niA)
      begin
        txd_qA <= '1;
      end
    else
      begin
        txd_qA <= txd_dA;
      end
  end

always_ff @( posedge clk_iB or negedge rst_niB )
  begin
    if (!rst_niB)
      begin
        txd_qB <= '1;
      end
    else
      begin
        txd_qB <= txd_dB;
      end
  end

always_ff @( posedge clk_iC or negedge rst_niC )
  begin
    if (!rst_niC)
      begin
        txd_qC <= '1;
      end
    else
      begin
        txd_qC <= txd_dC;
      end
  end

always_ff @( posedge clk_iA or negedge rst_niA )
  begin
    if (!rst_niA)
      begin
        state_qA <= TXIDLE;
      end
    else
      begin
        state_qA <= state_dA;
      end
  end

always_ff @( posedge clk_iB or negedge rst_niB )
  begin
    if (!rst_niB)
      begin
        state_qB <= TXIDLE;
      end
    else
      begin
        state_qB <= state_dB;
      end
  end

always_ff @( posedge clk_iC or negedge rst_niC )
  begin
    if (!rst_niC)
      begin
        state_qC <= TXIDLE;
      end
    else
      begin
        state_qC <= state_dC;
      end
  end

majorityVoter #(.WIDTH(3)) state_qVoterA (
    .inA(state_qA),
    .inB(state_qB),
    .inC(state_qC),
    .out({state_qVotedA}),
